    /*
     Optional float payload.
     */
    float param_f32;
    /*
     Optional uint32 payload.
     */
    uint32_t param_u32;
    /*
     Optional UTF-8 payload pointer (borrowed for the call).
     */
    const char *payload_utf8;
    /*
     Payload length in bytes.
     */
